// Single-flight: only one request per key recomputes on a miss
const inflight = new Map();
async function getUser(id) {
  const hit = await cache.get(`user:${id}`);
  if (hit) return hit;
  if (!inflight.has(id)) {
    inflight.set(id, db.loadUser(id)
      .then(async (u) => { await cache.set(`user:${id}`, u, { ttl: 300 + Math.random() * 60 }); return u; })
      .finally(() => inflight.delete(id)));
  }
  return inflight.get(id);
}
